  const int ih_min = oh0 - (KH - 1);
  const int iw_min = ow0 - (KW - 1);

  const int K_ALL = KD * KH * KW;
  const int sX_floats = C_CHUNK * D_IT * H_IT * W_IT;
  const int sW_floats = C_CHUNK * OC_T * K_ALL;

  extern __shared__ float smem_raw[];
  float* sX_ptr = smem_raw;
  float* sW_ptr = smem_raw + sX_floats;

  Tensor sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Int<C_CHUNK>{}, D_IT, H_IT, W_IT),
      make_stride(D_IT * H_IT * W_IT, H_IT * W_IT, W_IT, Int<1>{}));

  Tensor sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<C_CHUNK>{}, Int<OC_T>{}, KD, KH, KW),
      make_stride(OC_T * K_ALL, K_ALL, KH * KW, KW, Int<1>{}));

  const int64_t sXn = (int64_t)CI * DI * HI * WI;
  const int64_t sXc = (int64_t)DI * HI * WI;
  const int64_t sXd = (int64_t)HI * WI;
  const int64_t sXh = (int64_t)WI;

  const int64_t sYn = (int64_t)OC * DO * HO * WO;
  const int64_t sYc = (int64_t)DO * HO * WO;
  const int64_t sYd = (int64_t)HO * WO;
  const int64_t sYh = (int64_t)WO;

  const int64_t sWci = (int64_t)OC * K_ALL;
  const int64_t sWoc = (int64_t)K_ALL;
  const int64_t sWkd = (int64_t)KH * KW;
  const int64_t sWkh = (int64_t)KW;

  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(N, CI, DI, HI, WI),
      make_stride(sXn, sXc, sXd, sXh, Int<1>{}));

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(CI, OC, KD, KH, KW),
      make_stride(sWci, sWoc, sWkd, sWkh, Int<1>{}));

  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(N, OC, DO, HO, WO),
      make_stride(sYn, sYc, sYd, sYh, Int<1>{}));

  const int sp = tid % S_T;
  const int oc_half = tid / S_T;

  int ow_rel = sp % W_T;
  int tmp = sp / W_T;
  int oh_rel = tmp % H_T;
  int od_rel = tmp / H_T;

  const int od = od0 + od_rel;
  const int oh = oh0 + oh_rel;
  const int ow = ow0 + ow_rel;
  const bool valid_out = (od < DO) && (oh < HO) && (ow < WO);

  float acc[ACC_R];
#pragma unroll
  for (int r = 0; r < ACC_R; ++r) {
    const int oc_rel = oc_half + r * 2;
    const int oc = oc0 + oc_rel;
    float v = 0.0f;
    if (B != nullptr && oc < OC) v = (float)B[oc];
    acc[r] = v;
  }

  for (int c0 = 0; c0 < CI; c0 += C_CHUNK) {
    for (int idx = tid; idx < sX_floats; idx += THREADS) {
      int iw_rel = idx % W_IT;
      int t = idx / W_IT;
      int ih_rel = t % H_IT;
      t /= H_IT;
      int id_rel = t % D_IT;
      int c_rel = t / D_IT;

      const int ci = c0 + c_rel;
      const int id = id_min + id_rel;
      const int ih = ih_min + ih_rel;
      const int iw = iw_min + iw_rel;

      T v = T(0);
      if (ci < CI &&
          (unsigned)id < (unsigned)DI &&
          (unsigned)ih < (unsigned)HI &&
          (unsigned)iw < (unsigned)WI) {
        v = mX(n, ci, id, ih, iw);
      }
      sX(c_rel, id_rel, ih_rel, iw_rel) = v;
    }

    for (int idx = tid; idx < sW_floats; idx += THREADS) {
      int kw = idx % KW;
      int t = idx / KW;
      int kh = t % KH;
      t /= KH;
      int kd = t % KD;
      t /= KD;
      int oc_rel = t % OC_T;
      int c_rel = t / OC_T;

      const int ci = c0 + c_rel;
      const int oc = oc0 + oc_rel;
      T v = T(0);
      if (ci < CI && oc < OC) {
        v = mW(ci, oc, kd, kh, kw);
      }
      sW(c_rel, oc_rel, kd, kh, kw) = v;
    }

    __syncthreads();

#pragma unroll
    for (int c_rel = 0; c_rel < C_CHUNK; ++c_rel) {
      for (int kd = 0; kd < KD; ++kd) {
        const int id_rel = od_rel + (KD - 1) - kd;
        for (int kh = 0; kh < KH; ++kh) {
          const int ih_rel = oh_rel + (KH - 1) - kh;
          for (int kw = 0; kw < KW; ++kw) {
            const int iw_rel = ow_rel + (KW - 1) - kw;
            const float xv = (float)sX(c_rel, id_rel, ih_rel, iw_rel);
#pragma unroll
            for (int r = 0; r < ACC_R; ++r) {
              const int oc_rel = oc_half + r * 2;
              const float wv = (float)sW(c_rel, oc_rel, kd, kh, kw);
              acc[r] = fmaf(xv, wv, acc[r]);
            }
          }
        }
      }
    }

    __syncthreads();
  }

  if (valid_out) {
#pragma unroll
    for (int r = 0; r < ACC_R; ++r) {
      const int oc_rel = oc_half + r * 2;
      const int oc = oc0 + oc_rel;
      if (oc < OC) {
        mY(n, oc, od, oh, ow) = (T)acc[r];
      }
    }
  }
}

torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       std::vector<int64_t> stride,
                                       std::vector<int64_t> padding,
                                       std::vector<int64_t> output_padding,
                                       int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, CI, DI, HI, WI]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [CI, OC, KD, KH, KW]");
  TORCH_CHECK(stride.size() == 3 && padding.size() == 3 && output_padding.size() == 3,
              "stride/padding/output_padding must have length 3");
  TORCH_CHECK(groups == 1, "custom CUTE kernel currently supports groups=1");
  TORCH_CHECK(stride[0] == 1 && stride[1] == 1 && stride[2] == 1,
              "custom CUTE kernel currently supports stride=(1,1,1)");
  TORCH_CHECK(padding[0] == 0 && padding[1] == 0 && padding[2] == 0,
              "custom CUTE kernel currently supports padding=(0,0,0)");
  TORCH_CHECK(output_padding[0] == 0 && output_padding[1] == 0 && output_padding[2] == 0,
              "custom CUTE kernel currently supports output_padding=(0,0,0)");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(b_c.scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(b_c.dim() == 1, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  const int64_t N = x_c.size(0);
  const int64_t CI = x_c.size(1);
  const int64_t DI = x_c.size(2);
  const int64_t HI = x_c.size(3);
  const int64_t WI = x_c.size(4);

  TORCH_CHECK(w_c.size(0) == CI, "ConvTranspose3d weight.size(0) must equal in_channels");
  const int64_t OC = w_c.size(1);
  const int64_t KD = w_c.size(2);
  const int64_t KH = w_c.size(3);
  const int64_t KW = w_c.size(4);
  if (b_ptr != nullptr) {
    TORCH_CHECK(b_c.size(0) == OC, "bias must have shape [OC]");
  }

  const int64_t DO = (DI - 1) * stride[0] - 2 * padding[0] + (KD - 1) + output_padding[0] + 1;
  const int64_t HO = (HI - 1) * stride[1] - 2 * padding[1] + (KH - 1) + output_padding[1] + 1;
  const int64_t WO = (WI - 1) * stride[2] - 2 * padding[2] + (KW - 1) + output_padding[2] + 1;
  TORCH_CHECK(DO > 0 && HO > 0 && WO > 0, "invalid output shape");

  auto y = torch::empty({N, OC, DO, HO, WO}, x_c.options());

  constexpr int THREADS = 256;
  constexpr int D_T = 2;
  constexpr int H_T = 4;
  constexpr int W_T = 16;
  constexpr int OC_T = 16;
  constexpr int C_CHUNK = 4;

  const int D_IT = D_T + (int)KD - 1;
  const int H_IT = H_T + (int)KH - 1;
  const int W_IT = W_T + (int)KW - 1;

  const size_t sX_floats = (size_t)C_CHUNK * D_IT * H_IT * W_IT;
  const size_t sW_floats = (size_t)C_CHUNK * OC_T * KD * KH * KW;
  const size_t smem_bytes = (sX_floats + sW_floats) * sizeof(float);

  const int wtiles = (int)((WO + W_T - 1) / W_T);
  const int htiles = (int)((HO + H_T - 1) / H_T);
  const int dtiles = (int)((DO + D_T - 1) / D_T);

  dim3 block(THREADS);
  dim3 grid((unsigned)(wtiles * htiles * dtiles),
            (unsigned)((OC + OC_T - 1) / OC_T),
            (unsigned)N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv_transpose3d_s1_kernel<float>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem_bytes);
  }

  conv_transpose3d_s1_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)CI, (int)DI, (int)HI, (int)WI,
      (int)OC, (int)KD, (int)KH, (int)KW,
      (int)DO, (int)HO, (int)WO);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_s1_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
